if (Inputs.announcementId === undefined || String(Inputs.announcementId).length === 0) return;
Outputs.announcementId = String(Inputs.announcementId);
// 🔴 Scheme and host only. This string reaches every opted-in inbox, so
// a caller must not be able to put a path, a query or a fragment in it —
// and `new URL` throwing on rubbish is a `failure`, which is wired.
let origin = '';
try {
  const u = new URL(String(Inputs.siteUrl || ''));
  if (u.protocol === 'http:' || u.protocol === 'https:') origin = u.protocol + '//' + u.host;
} catch (e) {
  origin = '';
}
Outputs.origin = origin;
Outputs.ok();

function tpl002Rows(raw) {
  const list = raw && raw.items ? raw.items : (Array.isArray(raw) ? raw : []);
  const out = [];
  for (let i = 0; i < list.length; i++) {
    const m = list[i];
    const data = m && m.data ? m.data : m;
    const id = m && typeof m.getId === "function" ? m.getId() : (data && (data.id || data.objectId));
    out.push({ id: id, data: data || {} });
  }
  return out;
}
// Three producers — the query, the record and the request — so the
// readiness guard is on all of them. `title` may legitimately be blank;
// `undefined` is what "has not arrived" looks like.
if (Inputs.rows === undefined || Inputs.title === undefined) return;
const rows = tpl002Rows(Inputs.rows);
const queue = [];
let unmailable = 0;
let firstError = '';
for (let i = 0; i < rows.length; i++) {
  const d = rows[i].data;
  const to = d.email === undefined || d.email === null ? '' : String(d.email).trim();
  const token = d['unsubscribeToken'] === undefined || d['unsubscribeToken'] === null
    ? '' : String(d['unsubscribeToken']);
  if (to.length === 0) {
    unmailable++;
    if (!firstError) firstError = 'One member has no email address on their record.';
    continue;
  }
  // 🔴 An address with no unsubscribe key is NOT mailed. Sending somebody
  // mail they have no one-click way out of is the thing AC4 exists to
  // prevent, and skipping loudly is the only alternative to doing it.
  if (token.length === 0) {
    unmailable++;
    if (!firstError) firstError = 'One member’s record has no unsubscribe key, so they were not emailed.';
    continue;
  }
  queue.push({ to: to, token: token });
}
const title = Inputs.title === null ? '' : String(Inputs.title);
const body = Inputs.body === undefined || Inputs.body === null ? '' : String(Inputs.body);
const origin = Inputs.origin === undefined || Inputs.origin === null ? '' : String(Inputs.origin);
// 🔴 **Written WHOLE, every time, and `Component` is not per-request.**
// Measured, s14: a `planned` flag added here to stop a second plan
// re-entering made every LATER request return before it answered — four
// 30-second cloud-function timeouts — because `_componentScopes` is
// keyed by the component instance id and those are reused between
// invocations. So the scope survives the request that filled it, and
// the only safe use of it is state that is overwritten on the way in.
// See D35.
Component.tpl002 = {
  queue: queue, at: 0, sent: 0, failed: unmailable, firstError: firstError,
  title: title, body: body, origin: origin
};
if (queue.length === 0) {
  Outputs.sent = 0;
  Outputs.failed = unmailable;
  Outputs.error = firstError;
  Outputs.nobody();
  return;
}
Outputs.next();

const s = Component.tpl002;
// Nothing to pump. Reachable only if `plan` threw, which is wired.
if (!s) return;
// Record the send this run is the answer to. The FIRST run comes from
// `plan` and has no outcome to record, which is what `at === 0` means.
if (s.at > 0) {
  if (Inputs.outcome === 'sent') {
    s.sent++;
  } else {
    s.failed++;
    if (!s.firstError && Inputs.error) s.firstError = String(Inputs.error);
  }
}
if (s.at >= s.queue.length) {
  Outputs.sent = s.sent;
  Outputs.failed = s.failed;
  Outputs.error = s.firstError || '';
  Outputs.finished();
  return;
}
const row = s.queue[s.at];
s.at++;
// The link is per-member, because the token is. `encodeURIComponent` is
// not decoration: a token is opaque and may hold anything.
const link = s.origin.length > 0
  ? s.origin + '/unsubscribe?token=' + encodeURIComponent(row.token)
  : '';
const tail = link.length > 0
  ? '\n\nTo stop receiving these emails, open this link — you do not need to sign in:\n' + link
  : '\n\nTo stop receiving these emails, sign in and turn them off on your account page.';
Outputs.to = row.to;
Outputs.subject = s.title.length > 0 ? s.title : 'A new announcement';
Outputs.text = (s.title.length > 0 ? s.title + '\n\n' : '') + s.body + tail;
// Rule 2 in its sharpest form: the address and the `Do` leave from this
// node, in this order, so the mailer cannot be fired with the previous
// member’s address still in flight.
Outputs.send();

Outputs.outcome = 'failed';
// 🔴 Verbatim. When SMTP is unconfigured this string is
// `EmailConfigState.notConfiguredReason()`, which names the Backend
// Services panel — the one thing the moderator reading it has to open.
// A sentence of our own here would drift out of date with the product.
Outputs.error = Inputs.error === undefined || Inputs.error === null ? '' : String(Inputs.error);
Outputs.go();
